281					t.Errorf("the missing target must not be created, stat err=%v", statErr)
282				}
283				// The manifest is read-only input and must survive untouched.
284				manifest, readErr := os.ReadFile(manifestPath)
285				if readErr != nil {
286					t.Fatal(readErr)
287				}
288				if string(manifest) != manifestContent {
289					t.Errorf("the input manifest changed: %s", manifest)
290				}
291			})
292		}
293	}
