79					os.Exit(3)
80				}
81				return half, errors.New(reason)
82			}
83		case faultRename:
84			// The complete new table must be ready before the replacement is
85			// refused; markers are checked on the prepared temporary file.
86			markers := strings.Split(os.Getenv("WRAP_MARKERS"), ",")
87			batchreg.RenameTempFile = func(oldpath, newpath string) error {
88				if newpath != registry {
89					return harnessExit("rename must target %q, got %q", registry, newpath)
90				}
91				prepared, err := os.ReadFile(oldpath)
92				if err != nil {
93					return harnessExit("prepared temporary file is unreadable: %v", err)
94				}
95				for _, marker := range markers {
96					if !bytes.Contains(prepared, []byte(marker)) {
97						return harnessExit("prepared content is missing %q: %s", marker, prepared)
98					}
99				}
100				return errors.New(reason)
101			}
102		case faultNone:
103		default:
104			fmt.Fprintf(os.Stderr, "wrap harness: unknown fault %q\n", os.Getenv("WRAP_FAULT"))
105			return 3
106		}
107		args := []string{
108			"--registry", registry,
109			"--batch", os.Getenv("WRAP_BATCH"),
110			"--product", os.Getenv("WRAP_PRODUCT"),
111			"--quantity", os.Getenv("WRAP_QUANTITY"),
112			"--unit", os.Getenv("WRAP_UNIT"),
113		}
114		if err := runBatchRegister(args, os.Stdout); err != nil {
115			fmt.Fprintln(os.Stderr, "govflow:", err)
116			var ue *usageError
117			if errors.As(err, &ue) {
118				fmt.Fprint(os.Stderr, ue.usage)
119			}
