125	// The one legal registration request every scenario in this file submits:
126	// a batch id nothing registers, padded text and leading zeros that
127	// normalization removes, and CJK/emoji text that must survive verbatim.
128	const (
129		registerFailureBatchFlag    = " B-NEW-1 "
130		registerFailureProductFlag  = "新产品😀"
131		registerFailureQuantityFlag = "00042"
132		registerFailureUnitFlag     = " 千克 "
133	)
