157	// with the chosen fault and returns the child's exit code plus captured
158	// output. existingRegistry says whether the target file pre-exists, which
159	// decides which batch ids the fully prepared new table must contain.
160	func runRegisterChild(t *testing.T, registry string, fault saveFault, reason string, existingRegistry bool) (code int, stdout, stderr []byte) {
161		t.Helper()
162		exe, err := os.Executable()
163		if err != nil {
