225					code, stdout, stderr := runRegisterChild(t, registry, fault, causes[fault], existing)
226	
227					// The caller must observe a command failure, not a success.
228					if code != 1 {
229						t.Fatalf("exit code = %d, want 1; stderr:\n%s", code, stderr)
230					}
231					if len(bytes.TrimSpace(stdout)) != 0 {
232						t.Fatalf("stdout must stay empty on save failure, got %q", stdout)
233					}
234					msg := string(stderr)
235					// stderr must identify the command, the user-supplied registry
236					// path and the concrete save reason.
237					for _, want := range []string{
238						"govflow:",
239						"cannot save registry",
240						registry,
241						causes[fault],
242					} {
243						if !strings.Contains(msg, want) {
244							t.Fatalf("stderr must contain %q:\n%s", want, msg)
245						}
246					}
247					// The request is legal and conflict-free (proven by the success
248					// controls below); the failure wording must never masquerade as
249					// invalid input or a batch conflict.
250					for _, mustNot := range []string{
251						"usage:", "missing required flag", "invalid --",
252						"already registered", "conflicting field",
253					} {
254						if strings.Contains(msg, mustNot) {
255							t.Fatalf("a save failure must not be reported as %q:\n%s", mustNot, msg)
256						}
257					}
258	
259					if existing {
260						// The existing registry survives with exact bytes and
261						// modification time — no reformatting to "restore" it — and
262						// still loads with its original records, fields and order.
263						info, err := os.Stat(registry)
264						if err != nil {
265							t.Fatalf("the original registry must still exist: %v", err)
266						}
267						if !info.ModTime().Equal(registerFailurePinnedModTime) {
268							t.Fatalf("failed registration changed the registry mtime: got %v, want %v",
269								info.ModTime(), registerFailurePinnedModTime)
270						}
271						after := readFileSnapshot(t, registry)
272						if !bytes.Equal(after, originalBytes) {
273							t.Fatalf("failed registration changed the registry bytes:\nbefore: %s\nafter:  %s", originalBytes, after)
274						}
275						if bytes.Contains(after, []byte("B-NEW-1")) {
276							t.Fatalf("the new batch landed in the registry: %s", after)
277						}
278						stored := readStoredBatches(t, registry)
279						if len(stored) != len(registerFailureOriginalBatches) {
280							t.Fatalf("registry must keep exactly its original batches, got %+v", stored)
281						}
282						for i, want := range registerFailureOriginalBatches {
283							got := stored[i]
284							got.Status = ""
285							if got != want {
286								t.Fatalf("original record %d = %+v, want %+v", i+1, got, want)
287							}
288						}
289					} else {
290						// With no prior registry there must still be no file: not
291						// an empty registry, not a half-written record.
292						if _, err := os.Stat(registry); !os.IsNotExist(err) {
293							t.Fatalf("failed registration must not create the registry, stat err=%v", err)
294						}
295					}
296					assertNoSaveLeftovers(t, dir, filepath.Base(registry))
297				})
298			}
299		}
300	}
301	
302	// The success control against an existing registry: with the save healthy the
303	// very request that failed above registers. Stdout is exactly one JSON object
304	// carrying the normalized four fields plus status "created", the old records
305	// keep their order and the new batch is appended last.
306	func TestBatchRegisterCLISaveSuccessAgainstExistingRegistry(t *testing.T) {
307		dir := t.TempDir()
308		registry := filepath.Join(dir, "reg.json")
309		writeFile(t, registry, registerFailureRegistryJSON)
310		if err := os.Chtimes(registry, registerFailurePinnedModTime, registerFailurePinnedModTime); err != nil {
311			t.Fatal(err)
312		}
313	
314		stdout, err := registerCLI(t, registry,
315			registerFailureBatchFlag, registerFailureProductFlag,
316			registerFailureQuantityFlag, registerFailureUnitFlag)
317		if err != nil {
318			t.Fatalf("the legal request must register when the save does not fail: %v", err)
319		}
320	
321		created := decodeRegisterResult(t, stdout)
322		want := registerResult{Batch: "B-NEW-1", Product: "新产品😀", Quantity: 42, Unit: "千克", Status: "created"}
323		if created != want {
324			t.Fatalf("registration result = %+v, want %+v", created, want)
325		}
326	
327		// A real save must have happened, observable as a new mtime rather than
328		// the pinned one, and the new record agrees field by field with what the
329		// registry finally holds, appended after the untouched originals.
330		info, err := os.Stat(registry)
331		if err != nil {
332			t.Fatal(err)
333		}
334		if info.ModTime().Equal(registerFailurePinnedModTime) {
335			t.Fatal("a creating registration must replace the file; the pinned mtime survived")
336		}
337		stored := readStoredBatches(t, registry)
338		wantStored := append(append([]registerResult(nil), registerFailureOriginalBatches...),
339			registerResult{Batch: "B-NEW-1", Product: "新产品😀", Quantity: 42, Unit: "千克"})
340		if len(stored) != len(wantStored) {
341			t.Fatalf("registry holds %d records, want %d: %+v", len(stored), len(wantStored), stored)
342		}
343		for i, w := range wantStored {
344			got := stored[i]
345			got.Status = ""
346			if got != w {
347				t.Fatalf("stored record %d = %+v, want %+v", i+1, got, w)
348			}
349		}
350		assertNoSaveLeftovers(t, dir, filepath.Base(registry))
351	}
352	
353	// The success control with no prior registry: the file is created, readable,
354	// and holds exactly the one new batch.
355	func TestBatchRegisterCLISaveSuccessWithMissingRegistry(t *testing.T) {
356		dir := t.TempDir()
357		registry := filepath.Join(dir, "reg.json")
358	
359		stdout, err := registerCLI(t, registry,
360			registerFailureBatchFlag, registerFailureProductFlag,
361			registerFailureQuantityFlag, registerFailureUnitFlag)
362		if err != nil {
363			t.Fatalf("the legal request must register and create the registry: %v", err)
364		}
365	
366		created := decodeRegisterResult(t, stdout)
367		want := registerResult{Batch: "B-NEW-1", Product: "新产品😀", Quantity: 42, Unit: "千克", Status: "created"}
368		if created != want {
369			t.Fatalf("registration result = %+v, want %+v", created, want)
370		}
371	
372		stored := readStoredBatches(t, registry)
373		if len(stored) != 1 {
374			t.Fatalf("created registry holds %d records, want 1: %+v", len(stored), stored)
375		}
376		got := stored[0]
377		got.Status = ""
378		if got != (registerResult{Batch: "B-NEW-1", Product: "新产品😀", Quantity: 42, Unit: "千克"}) {
379			t.Fatalf("stored record = %+v, want the registered batch", got)
380		}
381		assertNoSaveLeftovers(t, dir, filepath.Base(registry))
382	}
383	
384	// The save-failure path must surface the quoted target path verbatim; this
385	// guards the wording the failure scenarios assert on, in a direct check that
386	// reads naturally when it breaks.
387	func TestBatchRegisterCLISaveFailureWordingNamesPath(t *testing.T) {
388		dir := t.TempDir()
389		registry := filepath.Join(dir, "reg.json")
390		writeFile(t, registry, registerFailureRegistryJSON)
391	
392		code, stdout, stderr := runRegisterChild(t, registry, faultRename, "injected replacement refusal", true)
393		if code != 1 {
394			t.Fatalf("exit code = %d, want 1; stderr:\n%s", code, stderr)
395		}
396		if len(stdout) != 0 {
397			t.Fatalf("stdout must be empty, got %q", stdout)
398		}
399		want := "cannot save registry " + strconv.Quote(registry) + ": injected replacement refusal"
400		if !strings.Contains(string(stderr), want) {
401			t.Fatalf("stderr must contain %q:\n%s", want, stderr)
402		}
403	}
