// resolveRegistryTarget returns the real file a save to path must replace,
// with every symbolic link — including links on DIRECTORY components — chased
// and every ".." applied to the directory it really leaves, the way the kernel
// resolves path for reads. The returned path is absolute and contains no
// symbolic-link or ".." component, so the save's temporary file is created in
// and renamed within the real target's own directory.
//
// This matters when path reaches a directory through a symbolic link and then
// steps back with "..": work/alias -> store/child makes work/alias/../x.json
// mean store/x.json, never work/x.json. Lexical cleaning (filepath.Clean or
// filepath.Dir) collapses alias/.. to work and would save into the wrong,
// possibly read-only directory; physical resolution is what keeps reads and
// saves pointing at the same file. Components of the path that do not exist
// yet (a first registration) are appended verbatim onto the longest existing
// prefix, so creating a new file needs write permission only in the directory
// that will really hold it.
//
// A dangling symbolic link, a link loop, or any link that cannot be resolved
// is an error, whether the link is the final component or one of the
// directories leading to it: the save must not create the target or overwrite
// the link as if this were a first registration.
func resolveRegistryTarget(path string) (string, error) {
	// Climb the path lexically only as far as components missing from the
	// filesystem; Lstat follows the kernel for every component but the last,
	// so a ".." right after a directory link is resolved physically here too.
	cur := filepath.Clean(path)
	var tail []string
	for {
		info, err := os.Lstat(cur)
		if err != nil {
			if parent := filepath.Dir(cur); errors.Is(err, fs.ErrNotExist) && parent != cur {
				tail = append(tail, filepath.Base(cur))
				cur = parent
				continue
			}
			return "", fmt.Errorf("cannot inspect registry path: %w", err)
		}
		// cur is the longest existing prefix. Resolve it physically: a valid
		// link yields its target (an absolute target, or a relative one
		// resolved against the link's own directory — never the process
		// working directory), while a dangling link or a loop fails here and
		// is reported as an unusable symbolic link rather than a fresh path.
		base, err := filepath.EvalSymlinks(cur)
		if err != nil {
			if info.Mode()&os.ModeSymlink != 0 {
				return "", fmt.Errorf("registry path is a symbolic link whose target cannot be resolved: %w", err)
			}
			return "", fmt.Errorf("cannot inspect registry path: %w", err)
		}
		target := base
		for i := len(tail) - 1; i >= 0; i-- {
			target = filepath.Join(target, tail[i])
		}
		return target, nil
	}
}

